  const comps=new Map();for(let p=0;p<labels.length;p++){const k=labels[p];if(!k)continue;const x=p%w,y=(p/w)|0;let c=comps.get(k);if(!c){c={l:x,t:y,r:x,b:y,n:0};comps.set(k,c)}if(x<c.l)c.l=x;if(x>c.r)c.r=x;if(y<c.t)c.t=y;if(y>c.b)c.b=y;c.n++}
  const keys=[...comps.keys()],parent=new Map(keys.map(k=>[k,k])),find=k=>{while(parent.get(k)!==k){parent.set(k,parent.get(parent.get(k)));k=parent.get(k)}return k};
  const gap=Math.max(3,Number(get('elementGroupGap').value)*Math.max(w,h)),big=.3*w*h;
  const small=keys.filter(k=>{const c=comps.get(k);return (c.r-c.l+1)*(c.b-c.t+1)<big}).sort((a,b)=>comps.get(a).l-comps.get(b).l);
  for(let i=0;i<small.length;i++){const a=comps.get(small[i]);for(let j=i+1;j<small.length;j++){const b=comps.get(small[j]);if(b.l-a.r>2.5*gap)break;const near=b.t-a.b<=gap&&a.t-b.b<=gap&&b.l-a.r<=gap,overlap=Math.min(a.b,b.b)-Math.max(a.t,b.t)+1,sameRow=overlap>=.4*Math.min(a.b-a.t+1,b.b-b.t+1)&&b.l-a.r<=2.5*gap;if(near||sameRow)parent.set(find(small[j]),find(small[i]))}}
  const groups=new Map();for(const k of keys){const g=find(k),c=comps.get(k);let o=groups.get(g);if(!o){o={l:c.l,t:c.t,r:c.r,b:c.b,n:0,keys:new Set()};groups.set(g,o)}o.l=Math.min(o.l,c.l);o.t=Math.min(o.t,c.t);o.r=Math.max(o.r,c.r);o.b=Math.max(o.b,c.b);o.n+=c.n;o.keys.add(k)}
  if(groups.size>60){status('الناتج '+groups.size+' جزءًا، وهذا كثير. اختر تجميعًا أكبر ثم أعد المحاولة.');return}
